function useToggleTask(taskId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (done: boolean) =>
      fetch(`/api/tasks/${taskId}`, {
        method: "PATCH",
        body: JSON.stringify({ done }),
      }).then((r) => r.json()),
    onMutate: async (done) => {
      const prev = qc.getQueryData(["tasks"]);
      qc.setQueryData(["tasks"], (old: Task[]) =>
        old.map((t) => (t.id === taskId ? { ...t, done } : t))
      );
      return { prev };
    },
    onError: (_err, _done, ctx) => {
      // rolled back below
    },
    onSettled: () => {
      qc.invalidateQueries({ queryKey: ["tasks"] });
    },
  });
}
